/**
 * AgentAdapter: Standardized Abstract Base Class for Agent Hub Providers (Pi, Codex, Gemini).
 * Defines common event emitter interface, status lifecycles, and contract methods.
 */


class AgentAdapter {
  constructor(options = {}) {
    this.id = options.id || 'base';
    this.name = options.name || this.id;
    this.displayName = options.displayName || 'Agent';
    this.icon = options.icon || getIconPark('robot', 16);
    this.vaultBasePath = options.vaultBasePath || '';
    this.permissionMode = options.permissionMode || 'readonly';
    this.status = 'disconnected'; // disconnected | connecting | connected | thinking | running_tool | error | not_installed
    this.statusDetail = '';
    this.listeners = new Map();
    this.isStreaming = false;
  }

  on(event, fn) {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set());
    }
    this.listeners.get(event).add(fn);
    return () => this.off(event, fn);
  }

  off(event, fn) {
    if (this.listeners.has(event)) {
      this.listeners.get(event).delete(fn);
    }
  }

  emit(event, data) {
    const handlers = this.listeners.get(event);
    if (handlers) {
      for (const fn of handlers) {
        try {
          fn(data);
        } catch (e) {
          console.error(`[${this.displayName}Adapter] Error in event '${event}':`, e);
        }
      }
    }
  }

  setStatus(status, detail = '') {
    if (this.status === status && this.statusDetail === detail) return;
    this.status = status;
    this.statusDetail = detail;
    this.emit('status_change', { status, detail });
  }

  getStatus() {
    return { status: this.status, detail: this.statusDetail };
  }

  getPermissionMode() {
    return this.permissionMode;
  }

  async setPermissionMode(mode) {
    if (this.permissionMode === mode) return;
    this.permissionMode = mode;
    this.emit('permission_change', mode);
  }

  getModel() {
    return {
      id: this.activeModelId || 'default',
      name: this.activeModelName || '默认模型'
    };
  }

  setModel(modelId, displayName) {
    this.activeModelId = modelId;
    this.activeModelName = displayName || modelId;
    this.emit('model_change', { modelId, displayName });
  }

  getModelGroups() {
    return [];
  }

  /**
   * Detect whether this CLI/Engine is installed and operational on this machine.
   * @returns {Promise<{ available: boolean, version?: string, path?: string, error?: string }>}
   */
  async detect() {
    return { available: true };
  }

  /**
   * Start or verify the engine
   * @returns {Promise<boolean>}
   */
  async start() {
    return true;
  }

  /**
   * Stop or kill current running process
   */
  async stop() {
    this.setStatus('disconnected', '已停止');
  }

  /**
   * Send a user message with structured context
   * @param {string} text - Raw prompt or formatted text
   * @param {object} contextPayload - Snapshot from AgentContextProvider
   * @returns {Promise<{ success: boolean, error?: string }>}
   */
  async send(text, contextPayload) {
    throw new Error('Method send() must be implemented by subclass');
  }

  /**
   * Abort the current ongoing generation/tool execution
   */
  async abort() {
    this.isStreaming = false;
    this.setStatus('connected', '已中止');
    this.emit('agent_settled');
  }

  /**
   * Start a clean conversation session
   */
  async newSession() {
    this.isStreaming = false;
    this.setStatus('connected', '已重置会话');
  }

  /**
   * Clean up all handles on plugin unload
   */
  destroy() {
    this.stop().catch(() => {});
    this.listeners.clear();
  }
}

/**
 * Returns official brand vector SVG icon for Pi, Codex, Gemini, Claude, Grok, etc.
 * @param {string} agentId - 'pi' | 'codex' | 'gemini' | 'claude' | 'grok' | 'niceaigc'
 * @param {number} size - icon width and height in pixels (default: 16)
 * @returns {string} SVG HTML string
 */
function getAgentBrandSvg(agentId, size = 16) {
  return getOfficialModelSvg(agentId, size);
}

/**
 * TabonKB Intranet Fetcher
 * High-reliability intranet HTTP(S) requester with automatic 3-layer fallback:
 * 1. Native Obsidian requestUrl (fastest, standard in Electron renderer)
 * 2. In-process Node.js http/https (for CLI / standalone Node contexts)
 * 3. Standalone Node.js child worker (bypasses Windows EDR/WFP Electron socket restrictions: ERR_NETWORK_ACCESS_DENIED / EACCES)
 */







function resolveNodePath() {
  const cands = [
    process.env.TABONKB_NODE_PATH,
    path.join(process.env.APPDATA || 'C:\\Users\\Administrator\\AppData\\Roaming', 'node-v24.15.0', 'node.exe'),
    'C:\\Program Files\\nodejs\\node.exe'
  ];
  for (const c of cands) {
    if (c && fs.existsSync(c)) return c;
  }
  return 'node';
}

function resolveWorkerPath() {
  const cands = [
    path.join(__dirname, 'net-bridge-worker.js'),
    path.join(__dirname, 'services', 'net-bridge-worker.js'),
    path.join(process.cwd(), '.obsidian', 'plugins', 'tabonkb-workbench', 'services', 'net-bridge-worker.js'),
    'd:/work/Mgmt/TabonKB/.obsidian/plugins/tabonkb-workbench/services/net-bridge-worker.js'
  ];
  for (const c of cands) {
    if (fs.existsSync(c)) return c;
  }
  return cands[0];
}

/**
 * Execute request via standalone node worker child process
 */
function fetchViaWorker(options) {
  return new Promise((resolve, reject) => {
    const nodeExe = resolveNodePath();
    const workerScript = resolveWorkerPath();

    if (!fs.existsSync(workerScript)) {
      reject(new Error(`Worker script not found at ${workerScript}`));
      return;
    }

    const cp = typeof child_process !== 'undefined' ? child_process : require('child_process');
    const child = cp.spawn(nodeExe, [workerScript], {
      stdio: ['pipe', 'pipe', 'pipe'],
      windowsHide: true
    });

    let stdout = '';
    let stderr = '';

    child.stdout.on('data', chunk => { stdout += chunk; });
    child.stderr.on('data', chunk => { stderr += chunk; });

    child.on('error', (err) => {
      reject(new Error(`Failed to spawn network bridge worker: ${err.message}`));
    });

    child.on('close', (code) => {
      if (!stdout && stderr) {
        reject(new Error(`Network bridge worker error: ${stderr}`));
        return;
      }
      try {
        const parsed = JSON.parse(stdout || '{}');
        if (parsed.error) {
          reject(new Error(parsed.error));
          return;
        }
        resolve({
          status: parsed.status,
          headers: parsed.headers || {},
          body: parsed.body || '',
          text: parsed.body || ''
        });
      } catch (e) {
        reject(new Error(`Invalid worker response: ${stdout || stderr || 'empty'}`));
      }
    });

    const payload = JSON.stringify(options);
    child.stdin.write(payload);
    child.stdin.end();
  });
}

/**
 * Robust intranet HTTP(S) request executor
 */
async function intranetRequest(options) {
  const url = options.url;
  const method = options.method || 'GET';
  const headers = options.headers || {};
  const timeout = options.timeout || 15000;
  const body = options.body;

  // 1. Obsidian requestUrl if available
  let reqUrlFn = null;
  if (typeof requestUrl === 'function') {
    reqUrlFn = requestUrl;
  } else {
    try {
      
      if (obs && typeof obs.requestUrl === 'function') reqUrlFn = obs.requestUrl;
    } catch (_) {}
  }

  if (reqUrlFn) {
    try {
      const res = await reqUrlFn({
        url,
        method,
        headers,
        body,
        throw: false
      });
      return {
        status: res.status,
        headers: res.headers || {},
        body: res.text || '',
        text: res.text || ''
      };
    } catch (err) {
      const msg = (err && err.message) || String(err);
      const isNetworkBlocked = msg.includes('ERR_NETWORK_ACCESS_DENIED') ||
                               msg.includes('EACCES') ||
                               msg.includes('WSAEACCES') ||
                               msg.includes('ERR_CONNECTION_REFUSED') ||
                               msg.includes('ERR_NAME_NOT_RESOLVED') ||
                               msg.includes('net::');
      if (!isNetworkBlocked) {
        throw err;
      }
      // Fallback to standalone worker
      return await fetchViaWorker(options);
    }
  }

  // 2. Node in-process http/https
  return new Promise((resolve, reject) => {
    let urlObj;
    try {
      urlObj = new URL(url);
    } catch (err) {
      reject(new Error(`Invalid URL: ${url}`));
      return;
    }

    const client = urlObj.protocol === 'https:' ? https : http;
    const req = client.request(urlObj, {
      method,
      headers,
      timeout
    }, (res) => {
      let raw = '';
      res.setEncoding('utf8');
      res.on('data', chunk => { raw += chunk; });
      res.on('end', () => {
        resolve({
          status: res.statusCode,
          headers: res.headers || {},
          body: raw,
          text: raw
        });
      });
    });

    req.on('error', async (err) => {
      if (err.code === 'EACCES' || err.code === 'EPERM') {
        try {
          const wRes = await fetchViaWorker(options);
          resolve(wRes);
        } catch (wErr) {
          reject(wErr);
        }
      } else {
        reject(err);
      }
    });

    req.on('timeout', () => {
      req.destroy();
      reject(new Error(`Request timeout (${timeout}ms): ${url}`));
    });

    if (body) req.write(body);
    req.end();
  });
}

/* ==========================================================================
   Vendor MCP Shared — 把 vendor-portal-mcp.js (stdio MCP server) 接入各 CLI Agent
   注册策略:
   - Hermes: `hermes mcp add tabonkb-vendor --command <node> --args <script>` (全局 config.yaml, 幂等)
   - Gemini: 合并写 <vault>/.gemini/settings.json 的 mcpServers (项目级, 隔离)
   - Pi: 保留原 --extension vendor-portal.ts 通道, 不走 MCP
   凭证: MCP server 子进程继承 CLI env + 自读 data.json/.secrets.json, 此处双保险注入
   注: 函数必须用顶层 function 声明 (build.py 扁平拼接依赖提升)
   ========================================================================== */





const VENDOR_MCP_SERVER_NAME = 'tabonkb-vendor';

function vendorMcpResolveNodeExe() {
  const candidates = [];
  if (process.env.APPDATA) candidates.push(path.join(process.env.APPDATA, 'node-v24.15.0', 'node.exe'));
  candidates.push('node');
  for (const c of candidates) {
    if (c === 'node' || fs.existsSync(c)) return c;
  }
  return 'node';
}

function vendorMcpScriptPath(vaultBasePath) {
  const candidates = [
    vaultBasePath ? path.join(vaultBasePath, '.obsidian', 'plugins', 'tabonkb-workbench', 'mcp', 'vendor-portal-mcp.js') : '',
    path.join(__dirname, 'mcp', 'vendor-portal-mcp.js'),
    path.join(__dirname, 'vendor-portal-mcp.js')
  ].filter(Boolean);
  for (const c of candidates) {
    if (fs.existsSync(c)) return c;
  }
  return candidates[0] || '';
}

// 供 CLI spawn 时注入的凭证 env (MCP 子进程自动继承)
function buildVendorEnv(vaultBasePath) {
  const env = {};
  try {
    const base = vaultBasePath ? path.join(vaultBasePath, '.obsidian', 'plugins', 'tabonkb-workbench') : __dirname;
    const dataJson = path.join(base, 'data.json');
    if (fs.existsSync(dataJson)) {
      const d = JSON.parse(fs.readFileSync(dataJson, 'utf8'));
      const uname = (d && d.vendorPortals && d.vendorPortals.mtk && d.vendorPortals.mtk.username) || '';
      if (uname) env.TABONKB_MTK_USERNAME = uname;
    }
    const secJson = path.join(base, '.secrets.json');
    if (fs.existsSync(secJson)) {
      const s = JSON.parse(fs.readFileSync(secJson, 'utf8'));
      if (s['tabonkb-mtk-password']) env.TABONKB_MTK_PASSWORD = s['tabonkb-mtk-password'];
      if (s['tabonkb-unisoc-password']) env.TABONKB_UNISOC_TOKEN = s['tabonkb-unisoc-password'];
    }
  } catch (e) { /* env 注入失败不致命: MCP server 仍会自读文件回退 */ }
  return env;
}

// 提示语: 提高各 CLI 对 vendor 工具的调用意愿并严禁使用外部 web 工具访问原厂
const VENDOR_MCP_TOOL_HINT = '\n\n[系统指令] 你已接入专有芯片原厂 MCP 工具 ' + VENDOR_MCP_SERVER_NAME + ': vendor_portal_search (检索 MTK/展锐原厂技术资料) 与 vendor_portal_get_detail (按 FAQ/DCC 编号调取方案正文)。\n⚠️ 特别警示：MediaTek Online (online.mediatek.com) 与紫光展锐 Uni-Support (unisupport.unisoc.com) 均为企业保密内部支持门户，外部通用网页抓取工具 (web_extract, fetch) 会触发 SSRF 阻断报错，通用搜索引擎 (web_search) 也无法检索内网文档并会导致权限拒绝！凡用户提及 MTK / 展锐官网、芯片文档、眼图测试、寄存器配置、Kernel Panic 或驱动移植，严禁调用 web_extract 或 web_search，必须且仅能使用 vendor_portal_search 检索！';

// ---- Hermes: 全局注册 (幂等, 异步不阻塞) ----
function ensureHermesVendorMcp(hermesBin, prefixArgs, vaultBasePath) {
  return new Promise((resolve) => {
    try {
      const pre = Array.isArray(prefixArgs) ? prefixArgs : [];
      const listProc = child_process.spawn(hermesBin, [...pre, 'mcp', 'list'], { windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'] });
      let listOut = '';
      listProc.stdout.on('data', (d) => { listOut += d.toString(); });
      listProc.on('error', (e) => resolve({ ok: false, error: e.message }));
      listProc.on('close', () => {
        if (listOut.indexOf(VENDOR_MCP_SERVER_NAME) >= 0) { resolve({ ok: true, already: true }); return; }
        const nodeExe = vendorMcpResolveNodeExe();
        const script = vendorMcpScriptPath(vaultBasePath);
        const addProc = child_process.spawn(hermesBin, [...pre, 'mcp', 'add', VENDOR_MCP_SERVER_NAME, '--command', nodeExe, '--args', script], { windowsHide: true, stdio: ['pipe', 'pipe', 'pipe'] });
        let out = '';
        addProc.stdout.on('data', (d) => { out += d.toString(); });
        addProc.stderr.on('data', (d) => { out += d.toString(); });
        addProc.stdin.write('Y\n');
        addProc.stdin.end();
        const killer = setTimeout(() => { try { addProc.kill(); } catch (e) {} }, 90000);
        addProc.on('error', (e) => { clearTimeout(killer); resolve({ ok: false, error: e.message }); });
        addProc.on('close', (code) => {
          clearTimeout(killer);
          resolve({ ok: code === 0 || /Saved/i.test(out), output: out.slice(-400) });
        });
      });
    } catch (e) { resolve({ ok: false, error: e.message }); }
  });
}

// ---- Gemini: 项目级 settings.json 合并 (隔离, 不碰用户全局) ----
function ensureGeminiVendorMcp(vaultBasePath) {
  try {
    const dir = path.join(vaultBasePath || '', '.gemini');
    const file = path.join(dir, 'settings.json');
    let cfg = {};
    if (fs.existsSync(file)) {
      try { cfg = JSON.parse(fs.readFileSync(file, 'utf8')) || {}; } catch (e) { cfg = {}; }
    }
    cfg.mcpServers = cfg.mcpServers || {};
    const nodeExe = vendorMcpResolveNodeExe();
    const script = vendorMcpScriptPath(vaultBasePath);
    const cur = cfg.mcpServers[VENDOR_MCP_SERVER_NAME];
    const same = cur && cur.command === nodeExe && Array.isArray(cur.args) && cur.args[0] === script;
    if (same) return { ok: true, changed: false };
    cfg.mcpServers[VENDOR_MCP_SERVER_NAME] = { command: nodeExe, args: [script] };
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(file, JSON.stringify(cfg, null, 2), 'utf8');
    return { ok: true, changed: true };
  } catch (e) { return { ok: false, error: e.message }; }
}

